import Observation

@Observable
class ItemStore {
    var items: [String] = []

    func addItem(_ item: String) {
        items.append(item)
    }
}

let store = ItemStore()
store.addItem("Keyboard")
store.addItem("Mouse")
print("Items count: \(store.items.count)")

import Observation

@Observable
class PlayerProfile {
    var username: String
    var points: Int
    @ObservationIgnored var sessionToken: String

    init(username: String, points: Int, sessionToken: String) {
        self.username = username
        self.points = points
        self.sessionToken = sessionToken
    }
}

let player = PlayerProfile(username: "Jordan", points: 150, sessionToken: "TOK_99")
print("\(player.username) has \(player.points) points with token \(player.sessionToken)")

import Observation

@Observable
class Counter {
    var count = 0
}

func observeModel() {
    let c = Counter()
    withObservationTracking {
        print("Initial: \(c.count)")
    } onChange: {
        print("Count will change")
    }
    c.count += 1
    print("Final: \(c.count)")
}

observeModel()
